(function () {
        'use strict';

            // --- 1. KONFIGURASI & VARIABEL UTAMA ---
                const CONFIG = {
                        pesanSingkat: "Happy birthday ya, sayang! 🎉 Wish you all the best: semoga makin panjang umur, sehat terus, rezekinya lancar, dan semua impian keren kamu terkabul tahun ini. Tetap jadi diri sendiri yang asik ya, dan semoga kita bisa terus bareng-bareng ke depannya. Enjoy your special day! 🥳🎂",
                                kecepatanKetik: 35,
                                        jumlahBalon: 20
                                            };

                                                let indexTeks = 0;
                                                    let sudahDiketiks = false;
                                                        let lilinMati = false;

                                                            // --- 2. ELEMEN DOM ---
                                                                const DOM = {
                                                                        messageBox: document.getElementById("messageBox"),
                                                                                typedText: document.getElementById("typedText"),
                                                                                        flame: document.getElementById("flame"),
                                                                                                balloonContainer: document.getElementById("balloon-container"),
                                                                                                        canvas: document.getElementById("fireworks-canvas")
                                                                                                            };

                                                                                                                // --- 3. FITUR PESAN & EFEK KETIK ---
                                                                                                                    window.bukaPesan = function() {
                                                                                                                            DOM.messageBox.style.display = "block";
                                                                                                                                    
                                                                                                                                            if (!sudahDiketiks) {
                                                                                                                                                        jalankanEfekKetik();
                                                                                                                                                                    sudahDiketiks = true;
                                                                                                                                                                            }
                                                                                                                                                                                    
                                                                                                                                                                                            jalankanKembangApi();
                                                                                                                                                                                                };

                                                                                                                                                                                                    function jalankanEfekKetik() {
                                                                                                                                                                                                            if (indexTeks < CONFIG.pesanSingkat.length) {
                                                                                                                                                                                                                        DOM.typedText.innerHTML += CONFIG.pesanSingkat.charAt(indexTeks);
                                                                                                                                                                                                                                    indexTeks++;
                                                                                                                                                                                                                                                setTimeout(jalankanEfekKetik, CONFIG.kecepatanKetik);
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                // --- 4. FITUR KLIK PADAMKAN LILIN ---
                                                                                                                                                                                                                                                                    window.padamkanLilinManual = function() {
                                                                                                                                                                                                                                                                            if (!lilinMati) {
                                                                                                                                                                                                                                                                                        lilinMati = true;
                                                                                                                                                                                                                                                                                                    DOM.flame.style.display = "none";
                                                                                                                                                                                                                                                                                                                jalankanKembangApi();
                                                                                                                                                                                                                                                                                                                            alert("Wih, lilinnya padam! Mantap, semoga doanya terkabul ya! 🚀");
                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                            // --- 5. FITUR BALON MELAYANG ---
                                                                                                                                                                                                                                                                                                                                                function buatBalon() {
                                                                                                                                                                                                                                                                                                                                                        if (!DOM.balloonContainer) return;
                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        const colors = ['#ff4757', '#ffa502', '#2ed573', '#1e90ff', '#ff6b81'];
                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                        for (let i = 0; i < CONFIG.jumlahBalon; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                    let balloon = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                balloon.className = "balloon";
                                                                                                                                                                                                                                                                                                                                                                                                                            balloon.style.left = Math.random() * 95 + "vw";
                                                                                                                                                                                                                                                                                                                                                                                                                                        balloon.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                                                                                                                                                                                                                                                                                                                                                                                                                                                    balloon.style.animationDelay = Math.random() * 6 + "s";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                balloon.style.animationDuration = (Math.random() * 4 + 6) + "s";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            DOM.balloonContainer.appendChild(balloon);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // --- 6. FITUR KEMBANG API (CANVAS) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let ctx, particles = [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function initCanvas() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!DOM.canvas) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx = DOM.canvas.getContext("2d");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function resize() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                DOM.canvas.width = window.innerWidth;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            DOM.canvas.height = window.innerHeight;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            window.addEventListener('resize', resize);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    resize();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function jalankanKembangApi() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!ctx) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const colors = ['#ff4757', '#ffa502', '#2ed573', '#1e90ff', '#ffffff'];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (let t = 0; t < 3; t++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let pusatX = Math.random() * DOM.canvas.width * 0.8 + DOM.canvas.width * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let pusatY = Math.random() * DOM.canvas.height * 0.5;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (let i = 0; i < 50; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let angle = Math.random() * Math.PI * 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let speed = Math.random() * 6 + 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                particles.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    x: pusatX,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        y: pusatY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            vx: Math.cos(angle) * speed,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                vy: Math.sin(angle) * speed,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alpha: 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: colors[Math.floor(Math.random() * colors.length)],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            size: Math.random() * 4 + 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function animateFireworks() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (ctx && DOM.canvas) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.clearRect(0, 0, DOM.canvas.width, DOM.canvas.height);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        particles.forEach((p, index) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p.x += p.vx;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p.y += p.vy;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p.vy += 0.05; // Gravitasi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p.alpha -= 0.015; // Pudar

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.globalAlpha = Math.max(p.alpha, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.fillStyle = p.color;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.fill();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.restore();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (p.alpha <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            particles.splice(index, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        requestAnimationFrame(animateFireworks);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // --- 7. INISIALISASI UTAMA SAAT HALAMAN DIMUAT ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    window.addEventListener("DOMContentLoaded", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            buatBalon();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    initCanvas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            animateFireworks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setTimeout(jalankanKembangApi, 600);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })();

